#!/bin/bash# Bash completion for "ollama run <model>"_ollama_completions() {    # Only activate if the command is "ollama run"    [[ "${COMP_WORDS[0]}" != "ollama" || "${COMP_WORDS[1]}" != "run" ]] && { COMPREPLY=(); return 0; }        # Ensure we are completing only the model argument (only one extra word)    [[ $COMP_CWORD -ne 2 ]] && return 0    # Handle colon completion if _get_comp_words_by_ref is available    local cur prev    if type _get_comp_words_by_ref &>/dev/null; then        _get_comp_words_by_ref -n : cur prev    else        cur="${COMP_WORDS[COMP_CWORD]}"        prev="${COMP_WORDS[COMP_CWORD-1]}"    fi    # Get list of models from "ollama list", skipping header and extracting first column.    local models=()    if command -v ollama &>/dev/null; then        models=( $(ollama list 2>/dev/null | tail -n +2 | awk '{print $1}') )    fi    # Sort the models for consistent order (compgen does not sort)    IFS=$'\n'    models=($(sort <<<"${models[*]}"))    unset IFS    # Generate completions using compgen with the sorted list of models    COMPREPLY=( $(compgen -W "${models[*]}" -- "$cur") )    # Adjust colon completions if __ltrim_colon_completions is available    if type __ltrim_colon_completions &>/dev/null; then        __ltrim_colon_completions "$cur"    fi}complete -F _ollama_completions ollama